<?php $title='Nouvelle intervention';require '../includes/header.php';$teams=db()->query("SELECT * FROM teams ORDER BY nom")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$ref='INT-'.date('YmdHis').'-'.random_int(100,999);$q=db()->prepare("INSERT INTO interventions(reference,type,description,priority,latitude,longitude,address,team_id,created_by,status) VALUES(?,?,?,?,?,?,?,?,?,'nouvelle')");$q->execute([$ref,$_POST['type'],$_POST['description'],$_POST['priority'],$_POST['latitude'],$_POST['longitude'],$_POST['address'],$_POST['team_id']?:null,user()['id']]);$id=db()->lastInsertId();if($_POST['team_id']){$q=db()->prepare("INSERT INTO notifications(user_id,intervention_id,type,title,message) SELECT user_id,?,IF(?='tres_urgent','urgent','intervention'),'Nouvelle intervention',? FROM team_members WHERE team_id=?");$q->execute([$id,$_POST['priority'],'Intervention '.$ref.' à prendre en charge',$_POST['team_id']]);}header('Location: index.php');exit;}?><h1>Nouvelle demande d'intervention</h1><form method="post" class="card"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Type</label><input name="type" required placeholder="Accident, agression..."></div><div class="field"><label>Priorité</label><select name="priority"><option>normal</option><option>urgent</option><option>tres_urgent</option></select></div><div class="field full"><label>Description</label><textarea name="description" rows="4"></textarea></div><div class="field"><label>Latitude</label><input id="latitude" name="latitude" required></div><div class="field"><label>Longitude</label><input id="longitude" name="longitude" required></div><div class="field full"><button type="button" class="btn secondary" onclick="locate('x','latitude','longitude')">📍 Utiliser ma position</button></div><div class="field"><label>Adresse / zone</label><input name="address"></div><div class="field"><label>Équipe</label><select name="team_id"><option value="">Non affectée</option><?php foreach($teams as $t):?><option value="<?=$t['id']?>"><?=e($t['nom'])?> — <?=e($t['secteur'])?></option><?php endforeach;?></select></div></div><br><button class="btn">Créer l'intervention</button></form><?php require '../includes/footer.php';?>